1|import { useId, useState } from "react";
2|import { approxPages, FREE_BOOK_MAX_WORDS } from "@/core/upload-policy";
3|
4|type Provider = "meta" | "openai";
5|
6|const REASONS: Record<"too_long" | "free_used", (pages: number) => string> = {
7|  too_long: (pages) => `This one is longer than about ${pages} pages, so it needs your own key.`,
8|  free_used: () => "You've already used your free book, so this one needs your own key.",
9|};
10|
11|// Key step only: no network call. The key lives in state and is cleared
12|// on submit, on reset, and on unmount; never stored, logged, or shared.
13|export function ByokStep({
14|  reason,
15|  onSubmit,
16|}: {
17|  reason: "too_long" | "free_used";
18|  onSubmit: () => void;
19|}) {
20|  const [provider, setProvider] = useState<Provider>("meta");
21|  const [key, setKey] = useState("");
22|  const [baseUrl, setBaseUrl] = useState("");
23|  const [model, setModel] = useState("");
24|  const privacyId = useId();
25|  const urlId = useId();
26|  const urlErrorId = useId();
27|  const freePages = approxPages(FREE_BOOK_MAX_WORDS);
28|
29|  const urlOk = baseUrl.trim() === "" || /^https:\/\//.test(baseUrl.trim());
30|  const ready =
31|    key.trim() !== "" && (provider === "meta" || (urlOk && baseUrl.trim() !== "" && model.trim() !== ""));
32|
33|  return (
34|    <div>
35|      <h3 className="ob-byok-t">Bring your own key!</h3>
36|      <p className="ob-note">{REASONS[reason](freePages)}</p>
37|      <div className="ob-radio-row" role="radiogroup" aria-label="Key provider">
38|        <label className="ob-radio">
39|          <input
40|            type="radio"
41|            name="byok-provider"
42|            checked={provider === "meta"}
43|            onChange={() => setProvider("meta")}
44|          />
45|          Meta <span className="ob-tag">Recommended</span>
46|        </label>
47|        <label className="ob-radio">
48|          <input
49|            type="radio"
50|            name="byok-provider"
51|            checked={provider === "openai"}
52|            onChange={() => setProvider("openai")}
53|          />
54|          OpenAI-compatible
55|        </label>
56|      </div>
57|      {provider === "openai" && (
58|        <>
59|          <label className="ob-field" htmlFor={urlId}>
60|            Base URL
61|            <input
62|              id={urlId}
63|              className="ob-input"
64|              type="url"
65|              value={baseUrl}
66|              onChange={(event) => setBaseUrl(event.target.value)}
67|              placeholder="https://"
68|              aria-invalid={!urlOk}
69|              aria-describedby={urlOk ? undefined : urlErrorId}
70|            />
71|          </label>
72|          {!urlOk && (
73|            <p className="ob-error" id={urlErrorId}>
74|              The base URL needs to start with https://.
75|            </p>
76|          )}
77|          <label className="ob-field">
78|            Model
79|            <input
80|              className="ob-input"
81|              value={model}
82|              onChange={(event) => setModel(event.target.value)}
83|            />
84|          </label>
85|        </>
86|      )}
87|      <label className="ob-field">
88|        Key
89|        <input
90|          className="ob-input"
91|          type="password"
92|          name="transient-key"
93|          autoComplete="off"
94|          spellCheck={false}
95|          value={key}
96|          onChange={(event) => setKey(event.target.value)}
97|          aria-describedby={privacyId}
98|        />
99|      </label>
100|      <p className="ob-note" id={privacyId}>
101|        Your key stays in this browser tab. It&apos;s never stored on our servers, and it&apos;s
102|        only used to process this book.
103|      </p>
104|      <div className="ob-actions">
105|        <button
106|          className="ob-action"
107|          type="button"
108|          disabled={!ready}
109|          onClick={() => {
110|            setKey("");
111|            onSubmit();
112|          }}
113|        >
114|          Read with soundtrack
115|        </button>
116|      </div>
117|    </div>
118|  );
