1|"use client";
2|
3|import { useEffect, useRef, useState } from "react";
4|import Link from "next/link";
5|import { EPUB_ERROR_MESSAGES, EpubError, readEpubFile, type EpubBook } from "@/core/epub";
6|import { approxPages, FREE_BOOK_MAX_WORDS, uploadRoute } from "@/core/upload-policy";
7|import { BookCard } from "./book-card";
8|import { ByokStep } from "./byok";
9|import { getFreeBookUsed, setFreeBookUsed } from "./free-book";
10|import { HomeIcon } from "./home-icons";
11|
12|type Status =
13|  | { step: "idle" }
14|  | { step: "reading" }
15|  | { step: "error"; message: string }
16|  | { step: "parsed"; book: EpubBook }
17|  | { step: "processing"; book: EpubBook };
18|
19|// Client-side only: files are parsed in the browser and never uploaded.
20|export function UploadSection() {
21|  const [status, setStatus] = useState<Status>({ step: "idle" });
22|  const [dragging, setDragging] = useState(false);
23|  const [freeUsed, setFreeUsed] = useState(false);
24|  const [coverUrl, setCoverUrl] = useState<string | null>(null);
25|  const [keyOpen, setKeyOpen] = useState(false);
26|  const inputRef = useRef<HTMLInputElement>(null);
27|  const resultRef = useRef<HTMLDivElement>(null);
28|  const freePages = approxPages(FREE_BOOK_MAX_WORDS);
29|
30|  useEffect(() => setFreeUsed(getFreeBookUsed()), []);
31|
32|  // The parsed and processing views replace the drop zone, so move focus
33|  // into the result; otherwise keyboard focus is lost when it unmounts.
34|  useEffect(() => {
35|    if (status.step === "parsed" || status.step === "processing") resultRef.current?.focus();
36|  }, [status]);
37|
38|  const book = status.step === "parsed" || status.step === "processing" ? status.book : null;
39|  useEffect(() => {
40|    if (!book?.cover) {
41|      setCoverUrl(null);
42|      return;
43|    }
44|    const url = URL.createObjectURL(new Blob([book.cover.bytes as BlobPart], { type: book.cover.mediaType }));
45|    setCoverUrl(url);
46|    return () => URL.revokeObjectURL(url);
47|  }, [book]);
48|
49|  async function openFile(file: File) {
50|    setStatus({ step: "reading" });
51|    try {
52|      setStatus({ step: "parsed", book: await readEpubFile(file) });
53|    } catch (err) {
54|      const message =
55|        err instanceof EpubError ? EPUB_ERROR_MESSAGES[err.code] : EPUB_ERROR_MESSAGES.unreadable;
56|      setStatus({ step: "error", message });
57|    }
58|  }
59|
60|  function reset() {
61|    if (inputRef.current) inputRef.current.value = "";
62|    setStatus({ step: "idle" });
63|  }
64|
65|  const route = status.step === "parsed" ? uploadRoute(status.book.words, freeUsed) : null;
66|
67|  return (
68|    <section className="ob-bring" aria-label="Bring your own book">
69|      {status.step === "processing" ? (
70|        <div ref={resultRef} tabIndex={-1}>
71|          <p className="ob-note">
72|            Soundtracks for your own books are coming soon. For now, Oz shows how it works.
73|          </p>
74|          <div className="ob-actions">
75|            <Link className="ob-action" href="/read/oz">
76|              Read Oz instead
77|            </Link>
78|            <button className="ob-quiet" type="button" onClick={reset}>
79|              Choose another book
80|            </button>
81|          </div>
82|        </div>
83|      ) : status.step === "parsed" && route ? (
84|        <div ref={resultRef} tabIndex={-1}>
85|          <BookCard book={status.book} coverUrl={coverUrl} />
86|          {route.kind === "free" ? (
87|            <div className="ob-actions">
88|              <button
89|                className="ob-action"
90|                type="button"
91|                onClick={() => {
92|                  setFreeBookUsed();
93|                  setFreeUsed(true);
94|                  setStatus({ step: "processing", book: status.book });
95|                }}
96|              >
97|                Read with soundtrack
98|              </button>
99|              <button className="ob-quiet" type="button" onClick={reset}>
100|                Choose another book
101|              </button>
102|            </div>
103|          ) : (
104|            <div>
105|              <ByokStep
106|                reason={route.reason}
107|                onSubmit={() => setStatus({ step: "processing", book: status.book })}
108|              />
109|              <div className="ob-actions">
110|                <button className="ob-quiet" type="button" onClick={reset}>
111|                  Choose another book
112|                </button>
113|              </div>
114|            </div>
115|          )}
116|        </div>
117|      ) : (
118|        <div>
119|          <div
120|            className={dragging ? "ob-drop over" : "ob-drop"}
121|            role="button"
122|            tabIndex={0}
123|            aria-label="Drop an EPUB here, or choose a file"
124|            onClick={() => inputRef.current?.click()}
125|            onKeyDown={(event) => {
126|              if (event.key === "Enter" || event.key === " ") {
127|                event.preventDefault();
128|                inputRef.current?.click();
129|              }
130|            }}
131|            onDragEnter={(event) => {
132|              event.preventDefault();
133|              setDragging(true);
134|            }}
135|            onDragOver={(event) => event.preventDefault()}
136|            onDragLeave={() => setDragging(false)}
137|            onDrop={(event) => {
138|              event.preventDefault();
139|              setDragging(false);
140|              const file = event.dataTransfer.files?.[0];
141|              if (file) void openFile(file);
142|            }}
143|          >
144|            <HomeIcon name="upload" />
145|            <p>
146|              Drop an EPUB here, or <span className="ob-pick">choose a file</span>
147|            </p>
148|            <small>EPUB only, up to 20 MB. Nothing leaves your computer until you choose to read it.</small>
149|            <input
150|              ref={inputRef}
151|              type="file"
152|              accept=".epub,application/epub+zip"
153|              hidden
154|              aria-hidden="true"
155|              tabIndex={-1}
156|              onChange={(event) => {
157|                const file = event.target.files?.[0];
158|                if (file) void openFile(file);
159|              }}
160|            />
161|          </div>
162|          <div aria-live="polite">
163|            {status.step === "reading" && <p className="ob-file">Opening your book…</p>}
164|            {status.step === "error" && (
165|              <div className="ob-file-row">
166|                <p className="ob-file ob-err">{status.message}</p>
167|                <button className="ob-quiet" type="button" onClick={reset}>
168|                  Try another file
169|                </button>
170|              </div>
171|            )}
172|          </div>
173|          <div className="ob-picks" role="group" aria-label="How much reading to take">
174|            <button
175|              type="button"
176|              className="ob-pickbtn"
177|              aria-pressed={!keyOpen}
178|              onClick={() => setKeyOpen(false)}
179|            >
180|              <span className="ob-box" aria-hidden="true">
181|                <HomeIcon name="check-box" />
182|              </span>
183|              <span>
184|                <b>Free</b>
185|                <small>Your first book is on us, up to about {freePages} pages.</small>
186|              </span>
187|            </button>
188|            <button
189|              type="button"
190|              className="ob-pickbtn"
191|              aria-pressed={keyOpen}
192|              aria-expanded={keyOpen}
193|              aria-controls="obKeybox"
194|              onClick={() => setKeyOpen((open) => !open)}
195|            >
196|              <span className="ob-keydoodle" aria-hidden="true">
197|                <HomeIcon name="key" />
198|              </span>
199|              <span>
200|                <b>Bring your own key!</b>
201|                <small>Longer books, or more of them? Use your own Meta key.</small>
202|              </span>
203|            </button>
204|          </div>
205|          <div className="ob-keybox" id="obKeybox" hidden={!keyOpen}>
206|            <p className="ob-fine">
207|              After your book opens, longer ones ask for your own Meta key. It stays in this tab only.
208|            </p>
209|          </div>
210|        </div>
211|      )}
212|    </section>
213|  );
214|}

