9|
10|(globalThis as unknown as Record<string, unknown>).IS_REACT_ACT_ENVIRONMENT = true;
11|
12|let container: HTMLDivElement;
13|let root: Root | null = null;
14|
15|function render(node: ReactNode) {
16|  act(() => {
17|    root?.render(node);
18|  });
19|}
20|
21|function click(el: HTMLElement) {
22|  act(() => {
23|    el.dispatchEvent(new MouseEvent("click", { bubbles: true }));
24|  });
25|}
26|
27|function button(): HTMLButtonElement {
28|  const el = container.querySelector("button");
29|  if (!el) throw new Error("stamp button missing");
30|  return el;
31|}
32|
33|function ringText(): string {
34|  return container.querySelector("textPath")?.textContent ?? "";
35|}
36|
37|function pill(): HTMLElement | null {
38|  return container.querySelector('[role="status"]');
39|}
40|
41|beforeEach(() => {
42|  document.documentElement.dataset.skin = "engraving";
43|  try {
44|    window.localStorage.clear();
45|  } catch {
46|    // jsdom without storage: the skin owner tolerates it.
47|  }
48|  container = document.createElement("div");
49|  document.body.appendChild(container);
50|  act(() => {
51|    root = createRoot(container);
52|  });
53|  render(<StyleStamp />);
54|});
55|
56|afterEach(() => {
57|  vi.useRealTimers();
58|  act(() => {
59|    root?.unmount();
60|  });
61|  root = null;
62|  container.remove();
63|});
64|
65|describe("style stamp", () => {
66|  it("names every skin on the ring, the aria-label and the title", () => {
67|    for (const skin of SKINS) {
68|      act(() => {
69|        setSkin(skin);
70|      });
71|      const name = SKIN_NAMES[skin];
72|      expect(button().getAttribute("aria-label")).toBe(`Change style, now ${name}`);
73|      expect(button().getAttribute("title")).toBe(`Change style, now ${name}`);
74|      expect(ringText()).toBe(`CHANGE STYLE \u2022 ${name.toUpperCase()} \u2022`);
75|    }
76|  });
77|
78|  it("cycles through the skin owner on click and persists the choice", () => {
79|    expect(getSkin()).toBe("engraving");
80|    click(button());
81|    expect(getSkin()).toBe("watercolor");
82|    expect(button().getAttribute("aria-label")).toBe("Change style, now Watercolor");
83|    // Never writes data-skin itself: skin.ts owns the attribute.
84|    expect(document.documentElement.dataset.skin).toBe("watercolor");
85|    try {
86|      expect(window.localStorage.getItem(SKIN_KEY)).toBe("watercolor");
87|    } catch {
88|      // jsdom without storage: the live value still applies.
89|    }
90|  });
91|
92|  it("shows the Now pill only after a click and hides it after about 1.8 s", () => {
93|    vi.useFakeTimers();
94|    expect(pill()?.classList.contains("style-stamp-show")).toBe(false);
95|    click(button());
96|    expect(pill()?.classList.contains("style-stamp-show")).toBe(true);
97|    expect(pill()?.textContent).toContain("Watercolor");
98|    act(() => {
99|      vi.advanceTimersByTime(1700);
100|    });
101|    expect(pill()?.classList.contains("style-stamp-show")).toBe(true);
102|    act(() => {
103|      vi.advanceTimersByTime(200);
104|    });
105|    expect(pill()?.classList.contains("style-stamp-show")).toBe(false);
106|  });
107|
108|  it("restarts the pill timer on rapid clicks and clears it on unmount", () => {
109|    vi.useFakeTimers();
110|    const clearSpy = vi.spyOn(globalThis, "clearTimeout");
111|    try {
112|      click(button());
113|      act(() => {
114|        vi.advanceTimersByTime(1500);
115|      });
116|      click(button());
117|      act(() => {
118|        vi.advanceTimersByTime(1500);
119|      });
120|      expect(pill()?.classList.contains("style-stamp-show")).toBe(true);
121|      const clearsBeforeUnmount = clearSpy.mock.calls.length;
122|      act(() => {
123|        root?.unmount();
124|      });
125|      root = null;
126|      expect(clearSpy.mock.calls.length).toBeGreaterThan(clearsBeforeUnmount);
127|    } finally {
128|      clearSpy.mockRestore();
129|    }
130|  });
131|
132|  it("renders the small variant with no ring text but the same label", () => {
133|    render(<StyleStamp size="small" />);
134|    expect(container.querySelector("textPath")).toBeNull();
135|    expect(button().getAttribute("aria-label")).toBe("Change style, now Engraving");
136|    expect(button().getAttribute("title")).toBe("Change style, now Engraving");
137|    // The brush medal stays.
138|    expect(button().querySelector("svg")).not.toBeNull();
139|  });
140|
141|  it("gives two stamps on one page different ring path ids", () => {
142|    render(
143|      <>
144|        <StyleStamp />
145|        <StyleStamp />
146|      </>,
147|    );
148|    const ids = [...container.querySelectorAll("defs path")].map((p) => p.getAttribute("id"));
149|    expect(ids).toHaveLength(2);
150|    expect(ids[0]).toBeTruthy();
151|    expect(ids[1]).toBeTruthy();
152|    expect(new Set(ids).size).toBe(2);
153|    const hrefs = [...container.querySelectorAll("textPath")].map((t) => t.getAttribute("href"));
154|    expect(new Set(hrefs).size).toBe(2);
155|    for (const href of hrefs) {
156|      expect(ids).toContain(href?.slice(1));
157|    }
158|  });
159|});

